#!/bin/sh
# Init script for FastMCP Server provider Docker dev environment.
# Auto-generated by ma-provider-tools — do not edit manually.
set -e

echo "==> Setting up FastMCP Server provider..."
export PYTHONPATH="/ma-server${PYTHONPATH:+:$PYTHONPATH}"
SOURCE_FILE=$(/app/venv/bin/python3 -c "import music_assistant; print(music_assistant.__file__)")
case "$SOURCE_FILE" in
  /ma-server/*) echo "==> MA source overlay: $SOURCE_FILE" ;;
  *) echo "ERROR: MA source overlay is inactive ($SOURCE_FILE)" >&2; exit 1 ;;
esac

# Install the same provider-specific runtime dependencies as the MA loader.
DEPS=$(/app/venv/bin/python3 - /ma-server/music_assistant/providers/fastmcp_server/manifest.json <<'PYEOF'
import json
import sys

with open(sys.argv[1], encoding="utf-8") as manifest_file:
    manifest = json.load(manifest_file)
print("\n".join(manifest.get("requirements", [])))
PYEOF
)
if [ -n "$DEPS" ]; then
    echo "==> Installing provider dependencies: $DEPS"
    # The official ghcr.io/music-assistant/server image ships uv but no pip
    # in the venv, so the bare `pip install` path crashes on
    # `/app/venv/bin/pip: not found`. Prefer uv when available; fall back
    # to pip for any image that still has it.
    if [ -x /app/venv/bin/uv ]; then
        printf '%s\n' "$DEPS" | /app/venv/bin/uv pip install --quiet --index-strategy unsafe-best-match --python /app/venv/bin/python -r -
    else
        printf '%s\n' "$DEPS" | /app/venv/bin/pip install --quiet -r -
    fi
fi

PROVIDER_FILE=$(/app/venv/bin/python3 -c "import music_assistant.providers.fastmcp_server; print(music_assistant.providers.fastmcp_server.__file__)")
case "$PROVIDER_FILE" in
  /ma-server/music_assistant/providers/fastmcp_server/*) echo "==> Provider source overlay: $PROVIDER_FILE" ;;
  *) echo "ERROR: provider source overlay is inactive ($PROVIDER_FILE)" >&2; exit 1 ;;
esac

echo "==> Starting Music Assistant..."
exec /usr/local/bin/entrypoint.sh --data-dir /data --cache-dir /data/.cache
